151	type Aggregate struct {
152		Available  bool
153		Running    int
154		CPUPercent float64
155		MemPercent float64
156	
157		// Cores is the daemon's CPU count, which is what CPUPercent was divided by.
158		// The dashboard prints it beside the figure for the same reason the host
159		// section prints its own: 40% of four cores and 40% of thirty-two do not
160		// describe the same machine.
161		Cores int
162	}
163	
164	// Capacity is what the daemon has to give, and therefore the denominator every
165	// percentage above is taken against.
166	type Capacity struct {
167		// Cores is `docker info`'s NCPU and MemTotal its memory, both as the
168		// *daemon* sees them — which on Windows and macOS is the VM's allocation
169		// and not the machine's. Reading the host's core count instead would be
170		// wrong on exactly the two platforms where Docker is not the host.
171		Cores    int
172		MemTotal int64
173	}
174	
175	// OK reports whether the capacity can serve as a denominator.
176	func (c Capacity) OK() bool { return c.Cores > 0 && c.MemTotal > 0 }
177	
178	// FetchCapacity reads what the daemon has, from `docker info`.
179	//
180	// It is read on every aggregate rather than memoized, and the 240 ms it costs
181	// (measured, against the 1–2 s `docker stats` already spends) is what buys it:
182	// a Docker Desktop reconfigured with a new CPU allocation changes this number
183	// under a running DevDesk, and a memo would divide by the old one for the life
184	// of the process — silently, since a wrong denominator still produces a
185	// plausible percentage.
186	func FetchCapacity() (Capacity, error) {
187		if err := requireDocker(); err != nil {
188			return Capacity{}, err
189		}
190		output, err := dockerOutput("info", "--format", "{{.NCPU}}\t{{.MemTotal}}")
191		if err != nil {
192			return Capacity{}, wrapErr("docker info", err)
193		}
194	
195		fields := strings.SplitN(strings.TrimSpace(string(output)), "\t", 2)
196		if len(fields) < 2 {
197			return Capacity{}, fmt.Errorf("docker info: unreadable capacity %q", output)
198		}
199		cores, err := strconv.Atoi(strings.TrimSpace(fields[0]))
200		if err != nil {
201			return Capacity{}, fmt.Errorf("docker info: unreadable NCPU %q: %w", fields[0], err)
202		}
203		total, err := strconv.ParseInt(strings.TrimSpace(fields[1]), 10, 64)
204		if err != nil {
205			return Capacity{}, fmt.Errorf("docker info: unreadable MemTotal %q: %w", fields[1], err)
206		}
207		return Capacity{Cores: cores, MemTotal: total}, nil
208	}
209	
210	// FetchAggregateMetrics reports what the running containers are using, as a
211	// share of what the daemon has.
212	//
213	// `docker stats --no-stream` costs about two seconds, measured: that is what
214	// earns it its own clock rather than a turn in the fast refresh.
215	//
216	// A capacity it cannot read makes the whole thing unavailable rather than a
217	// number on an unstated scale. That is the choice this function exists to make:
218	// the raw sums are not percentages, so there is nothing honest to show without
219	// their denominator — and `-` is a word this dashboard already has.
220	func FetchAggregateMetrics() Aggregate {
221		metrics, err := GetContainerMetrics()
222		if err != nil {
223			log.Printf("ERROR [docker] aggregate metrics: %v", err)
224			return Aggregate{}
225		}
226	
227		capacity, err := FetchCapacity()
228		if err != nil {
229			log.Printf("ERROR [docker] aggregate capacity: %v", err)
230			return Aggregate{}
231		}
232		if !capacity.OK() {
233			log.Printf("ERROR [docker] aggregate capacity: daemon reports %d cores and %d bytes",
234				capacity.Cores, capacity.MemTotal)
235			return Aggregate{}
236		}
237	
238		return aggregate(metrics, capacity)
239	}
240	
241	// aggregate is the arithmetic on its own, so a test can hand it readings rather
242	// than a daemon.
243	func aggregate(metrics map[string]Container, capacity Capacity) Aggregate {
244		agg := Aggregate{Available: true, Running: len(metrics), Cores: capacity.Cores}
245	
246		var memBytes int64
247		for _, c := range metrics {
248			agg.CPUPercent += c.CPUPercent
249			memBytes += c.MemBytes
250		}
251		agg.CPUPercent /= float64(capacity.Cores)
252		agg.MemPercent = float64(memBytes) / float64(capacity.MemTotal) * 100
253		return agg
254	}
